"""Registrar leituras e inspeção visual do lote C-03 (registro 133)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['primeira_prova'];N=len(m['paginas']);assert N==11
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,12)),same
notes={1:'Abertura do registro de dedicação: identificação do ciclo em lista com linhas; quadro de atividades.',2:'Fechamento; exemplo de Rina e Mei com quadro de seis linhas; entrada proporcional e conferência pendente.',3:'Abertura do registro de Pactos e Promessas; folha em branco em largura cheia.',4:'Exemplo do Overtime; conferência rápida de uma Promessa e exemplo de Promessa.',5:'Abertura do registro de entidade; quadros de aquisição e de projeto.',6:'Fim do quadro de projeto; exemplo da calígrafa; estado para passagem entre mesas.',7:'Exemplos de ritual, doma, construção, transporte e fabricação; abertura da ficha de inimigo e quadro 1.',8:'Campos com linhas; bloco 2 e início do bloco 3.',9:'Fim do bloco 3; bloco 4 com quadro de lugar; bloco 5 com caixas de marcar sem marcador duplo.',10:'Bloco 6 e fecho; abertura da conferência de habilidade.',11:'Perguntas para as interações em largura cheia; exemplo do Agarrar do Carregador.'}
save('revisao-final.json',{'registro':133,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das cinco fichas e das regras citadas, cinco cópias, remissões para os capítulos novos e clareza.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura da prova completa, trechos alterados no contexto e varredura de crase, repetições e termos de produção; nenhuma alteração necessária.'}],'ajuste_de_diagramacao':'Linhas de preenchimento nos campos da dedicação e da ficha de inimigo; os registros de Pactos e de entidade e a conferência de habilidade são quadros de orientação, sem linhas. Campos unidos por quebra de linha separados, cada um com suas linhas; caixas de marcar na lista Antes de jogar; quadro de perguntas em largura cheia.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if False else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','Espaço de fechamento no pé da página 3, antes do exemplo do Overtime; reavaliar na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s040':[1,2],'s042':[3,4],'s044':[5,7],'s058':[7,10],'s061':[10,11]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':133,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':133,'lote':'C-03','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':59,'casos_pendentes':0,'lotes_pendentes':0,'consultas_revistas':15,'consultas_pendentes':2,'consultas_complementares_pendentes':2,'etapa_6':'em andamento','proximo_lote':'C-04','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
